using System.Collections.Generic;public class Solution{public bool CanFinish(int n,int[][]p){var g=new List<int>[n];for(int i=0;i<n;i++)g[i]=new();int[]d=new int[n];foreach(var e in p){g[e[1]].Add(e[0]);d[e[0]]++;}var q=new Queue<int>();for(int i=0;i<n;i++)if(d[i]==0)q.Enqueue(i);int c=0;while(q.Count>0){int u=q.Dequeue();c++;foreach(int v in g[u])if(--d[v]==0)q.Enqueue(v);}return c==n;}}
